-- 212 (15/11, lô 48): 26 bài NÓI B2 cho cây Luyện tập (B2-PO-1 đến PO-4, các dòng « Cần soạn » của Excel kế hoạch).
-- Sinh bởi scripts/nhap/lo48_noi_b2.mjs. PO-1, PO-2 là phần chuẩn bị (viết); PO-3, PO-4 ghi âm (meta.ghiAm). time_limit 5/30/30 cho ba bài chuẩn bị chốt.
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2po01jrg01t', 'practice', 'Oral B2 : du document au problème', 'B2', array['Production orale']::text[], 'practice', null, null, '<p>À l''examen, vous tirez au sort un court document. Votre première tâche est d''en dégager le problème, c''est-à-dire la question qui fait débat. Lisez les trois documents et répondez.</p>', '<p><strong>Document 1. Des heures calmes au supermarché</strong></p><p>Dans plusieurs villes, des magasins proposent désormais des « heures calmes » : lumière tamisée, musique coupée, caisses sans bip. L''idée est née pour les personnes autistes, mais de nombreux clients disent apprécier ce moment de tranquillité. Certains commerçants craignent pourtant de perdre du chiffre d''affaires.</p><p><strong>Document 2. Pas de courriels le vendredi</strong></p><p>Une entreprise nantaise a supprimé les courriels internes le vendredi : les salariés doivent se parler directement ou par téléphone. Selon la direction, le stress a diminué. Selon certains employés, il est devenu plus difficile de garder une trace des décisions.</p><p><strong>Document 3. Des parents qui suivent tout</strong></p><p>De plus en plus de parents installent sur le téléphone de leurs adolescents une application qui permet de suivre leurs déplacements en temps réel. Ils disent vouloir les protéger. Des psychologues s''inquiètent : la confiance peut-elle exister sous une surveillance permanente ?</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• dégager (verbe) : rút ra\n• tamisé (adjectif) : (ánh sáng) dịu\n• le chiffre d''affaires (nom masculin) : doanh thu\n• garder une trace (expression) : lưu lại dấu vết\n• la surveillance (nom féminin) : sự giám sát","explications":"• Vấn đề (problème) không phải đề tài: « le téléphone des ados » là đề tài, « peut-on surveiller sans détruire la confiance ? » là vấn đề.\n• Tìm trong tài liệu hai phía đối lập (mais, pourtant, selon … selon …): vấn đề nằm giữa hai phía đó.","kyNang":"B2-PO-1","vong":"hoc","thuTu":1}'::jsonb, '2026-11-15T12:00:00.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh9kjr7000', 'b2po01jrg01t', 1, 'qcm', 'Document 1 : quel est le problème posé ?', '{"options":["Les personnes autistes font-elles leurs courses au supermarché ?","Combien de magasins proposent aujourd''hui des heures calmes dans les grandes villes du pays ?","Faut-il adapter les commerces au besoin de calme des clients, même si cela coûte ?"]}'::jsonb, '{"answer":2}'::jsonb, 'Tài liệu đặt hai phía đối lập: khách « disent apprécier ce moment de tranquillité », còn chủ cửa hàng « craignent pourtant de perdre du chiffre d''affaires ». Vấn đề là câu hỏi có thể tranh luận, không phải câu hỏi số liệu.'), ('qmwh9kjr7001', 'b2po01jrg01t', 2, 'qcm', 'Document 2 : quel est le problème posé ?', '{"options":["Comment écrire un courriel professionnel clair et poli ?","Pourquoi l''entreprise a-t-elle choisi de s''installer à Nantes plutôt qu''à Paris ?","Moins de courriels au travail, est-ce moins de stress ou moins d''efficacité ?"]}'::jsonb, '{"answer":2}'::jsonb, 'Hai ý kiến trái ngược: « le stress a diminué » và « plus difficile de garder une trace des décisions ». Vấn đề nằm ở sự cân nhắc giữa hai mặt đó.'), ('qmwh9kjr7002', 'b2po01jrg01t', 3, 'open', 'Document 3 : écrivez le problème posé, sous forme de question. (12 mots minimum)', '{}'::jsonb, '{"model":"Peut-on protéger ses enfants en surveillant leurs déplacements sans détruire la confiance entre parents et adolescents ?"}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2po02jrj01u', 'practice', 'Oral B2 : la problématique', 'B2', array['Production orale']::text[], 'practice', null, null, '<p>Une bonne problématique est une question ouverte, qui peut recevoir plusieurs réponses argumentées. Choisissez, puis formulez vos propres problématiques.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une problématique (nom féminin) : câu hỏi vấn đề\n• ouvert (adjectif) : mở\n• se soucier de (verbe) : quan tâm, lo cho\n• la fréquentation (nom féminin) : lượng khách\n• menacer (verbe) : đe doạ","explications":"• Ba mẫu câu hữu ích: « Faut-il … ? », « Peut-on … ? », « … est-il / est-elle vraiment … ? ».\n• Thử trả lời câu hỏi của mình bằng « oui, parce que » rồi « non, parce que ». Cả hai đều được thì đó là problématique tốt.","kyNang":"B2-PO-1","vong":"hoc","thuTu":2}'::jsonb, '2026-11-15T12:00:01.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh9kjr7003', 'b2po02jrj01u', 1, 'qcm', 'Thème : le télétravail. Quelle est la meilleure problématique ?', '{"options":["Le télétravail améliore-t-il vraiment la qualité de vie des salariés ?","Combien de salariés français pratiquent le télétravail chaque semaine ?","Le télétravail existe depuis plusieurs années dans les grandes entreprises."]}'::jsonb, '{"answer":0}'::jsonb, '« améliore-t-il vraiment »: câu hỏi mở, trả lời được bằng lập luận cho hoặc chống. Câu kể không phải câu hỏi; câu hỏi « combien » chỉ cần một con số.'), ('qmwh9kjr7004', 'b2po02jrj01u', 2, 'qcm', 'Thème : les voyages en avion. Quelle est la meilleure problématique ?', '{"options":["Peut-on encore voyager en avion quand on se soucie de l''environnement ?","Quel est le prix moyen d''un billet d''avion entre Paris et Hanoï ?","Les voyages en avion polluent beaucoup plus que les voyages en train ou en car."]}'::jsonb, '{"answer":0}'::jsonb, '« Peut-on encore … quand on se soucie de l''environnement »: đặt hai giá trị (du lịch, môi trường) đối diện nhau, mở ra tranh luận.'), ('qmwh9kjr7005', 'b2po02jrj01u', 3, 'qcm', 'Quelle question n''est PAS une bonne problématique ?', '{"options":["Le numérique menace-t-il la fréquentation des musées ?","Les musées devraient-ils être gratuits pour tous ?","Quand le premier musée a-t-il ouvert en France ?"]}'::jsonb, '{"answer":2}'::jsonb, '« Quand le premier musée a-t-il ouvert » là câu hỏi kiến thức, trả lời bằng một ngày tháng, không có gì để tranh luận.'), ('qmwh9kjr7006', 'b2po02jrj01u', 4, 'open', 'Thème : les réseaux sociaux et la politique. Formulez une problématique. (8 mots minimum)', '{}'::jsonb, '{"model":"Les réseaux sociaux rendent-ils le débat politique plus démocratique ou plus violent ?"}'::jsonb, null), ('qmwh9kjr7007', 'b2po02jrj01u', 5, 'open', 'Thème : apprendre une langue avec l''intelligence artificielle. Formulez une problématique. (8 mots minimum)', '{}'::jsonb, '{"model":"L''intelligence artificielle peut-elle remplacer un professeur pour apprendre une langue étrangère ?"}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2po03jrj01v', 'practice', 'Oral B2 : résumer ou analyser ?', 'B2', array['Production orale']::text[], 'practice', null, null, '<p>À l''examen, l''erreur la plus fréquente est de résumer le document au lieu d''en dégager le problème. Lisez le document, puis répondez.</p>', '<p><strong>Le boom des livres audio</strong></p><p>Les ventes de livres audio ont doublé en cinq ans. On les écoute dans les transports, en faisant du sport ou la cuisine. Pour certains enseignants, écouter un livre, ce n''est pas vraiment lire : l''attention serait moins grande et le vocabulaire moins bien retenu. Les éditeurs, eux, y voient un moyen de ramener vers les histoires des personnes qui ne lisaient plus.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un résumé (nom masculin) : bản tóm tắt\n• doubler (verbe) : tăng gấp đôi\n• retenir (verbe) : ghi nhớ\n• un éditeur (nom masculin) : nhà xuất bản\n• séduire (verbe) : hấp dẫn","explications":"• Mở bài exposé B2 = một câu bối cảnh + problématique + báo trước dàn ý. Không quá một câu cho nội dung tài liệu.\n• Giám khảo đã đọc tài liệu rồi: kể lại tài liệu là mất thời gian và mất điểm.","isPremium":true,"price":19000,"kyNang":"B2-PO-1","vong":"hoc","thuTu":3}'::jsonb, '2026-11-15T12:00:02.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh9kjr7008', 'b2po03jrj01v', 1, 'qcm', 'Laquelle de ces phrases est un RÉSUMÉ, et non une problématique ?', '{"options":["Le document dit que les ventes de livres audio ont doublé et qu''on les écoute partout.","Écouter un livre, est-ce encore vraiment lire ?","Le livre audio éloigne-t-il les jeunes de la lecture ou, au contraire, les y ramène-t-il ?"]}'::jsonb, '{"answer":0}'::jsonb, 'Câu này chỉ chép lại thông tin của tài liệu (« ont doublé », nghe ở mọi nơi) mà không đặt câu hỏi nào.'), ('qmwh9kjr7009', 'b2po03jrj01v', 2, 'qcm', 'Quelle phrase introduit le mieux l''exposé ?', '{"options":["Les ventes ont doublé en cinq ans, ce qui est un chiffre très important pour l''édition.","Ce document parle des livres audio, des enseignants, des éditeurs et de leurs avis très différents sur l''écoute des livres aujourd''hui.","Si le livre audio séduit de plus en plus, on peut se demander s''il remplace la lecture ou s''il en offre une nouvelle forme."]}'::jsonb, '{"answer":2}'::jsonb, 'Câu tốt nhắc ngắn bối cảnh (« séduit de plus en plus ») rồi nêu vấn đề (« on peut se demander »). Hai câu kia chỉ kể lại nội dung.'), ('qmwh9kjr700a', 'b2po03jrj01v', 3, 'open', 'Écrivez l''introduction de votre exposé : une phrase de contexte, la problématique, puis l''annonce de votre plan. Ne résumez pas le document. (35 mots minimum)', '{}'::jsonb, '{"model":"Aujourd''hui, beaucoup de gens écoutent des livres pendant leurs trajets ou leurs activités. Mais écouter un livre, est-ce encore lire ? Je montrerai d''abord que le livre audio n''offre pas exactement la même expérience que la lecture, puis qu''il peut malgré tout ramener vers les histoires ceux qui avaient abandonné les livres."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2po04jrk01w', 'practice', 'Oral B2 : quel enjeu ?', 'B2', array['Production orale']::text[], 'practice', null, null, '<p>Voici deux nouveaux documents. Pour chacun, écrivez le problème posé et indiquez en une phrase la position que vous défendriez.</p>', '<p><strong>Document A. Le supermarché sans caissiers</strong></p><p>Une chaîne de supermarchés teste des magasins sans caissiers : on scanne ses produits avec son téléphone, puis on sort. Les clients gagnent du temps. Les syndicats dénoncent la disparition de milliers d''emplois et la fin d''un lien social important pour les personnes âgées.</p><p><strong>Document B. Un café racheté par ses clients</strong></p><p>Dans un village du Jura, les habitants ont racheté ensemble le dernier café pour qu''il ne ferme pas. Chacun a versé entre 50 et 500 euros. Ailleurs, ce sont des épiceries ou des librairies qui sont sauvées par leurs clients. Mais peut-on compter sur la générosité des habitants pour maintenir les services dans les campagnes ?</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un enjeu (nom masculin) : điều được mất, vấn đề cốt lõi\n• un syndicat (nom masculin) : công đoàn\n• dénoncer (verbe) : lên án\n• le lien social (nom masculin) : sự gắn kết xã hội\n• maintenir (verbe) : duy trì","explications":"• Đôi khi tài liệu đã có sẵn câu hỏi (như Document B): vẫn nên nói lại bằng lời của mình.\n• Lập trường B2 thường có sắc thái: « plutôt pour, à condition que … ».","isPremium":true,"price":19000,"kyNang":"B2-PO-1","vong":"on","thuTu":4}'::jsonb, '2026-11-15T12:00:03.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh9kjr700b', 'b2po04jrk01w', 1, 'open', 'Document A : problème et position. (25 mots minimum)', '{}'::jsonb, '{"model":"Problème : faut-il accepter l''automatisation des magasins si elle fait gagner du temps aux clients mais supprime des emplois et du lien social ?\nPosition : je suis plutôt contre une automatisation totale ; il faut garder des caisses avec du personnel."}'::jsonb, null), ('qmwh9kjr700c', 'b2po04jrk01w', 2, 'open', 'Document B : problème et position. (25 mots minimum)', '{}'::jsonb, '{"model":"Problème : est-ce aux habitants de sauver eux-mêmes les commerces de village, ou est-ce le rôle de l''État et des communes ?\nPosition : ces initiatives sont admirables, mais elles ne doivent pas remplacer une vraie politique pour les campagnes."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2po05jrk01x', 'practice', 'Oral B2 : un document, un problème', 'B2', array['Production orale']::text[], 'practice', null, 5, '<p>Comme au début de la préparation : vous avez 5 minutes. Lisez le document et notez le problème, votre position et l''annonce de votre plan.</p>', '<p><strong>Un examen remplacé par un projet</strong></p><p>Depuis septembre, une université propose à ses étudiants de remplacer un examen écrit par un projet réalisé en groupe avec une association locale. Les étudiants inscrits sont enthousiastes : ils se sentent utiles et apprennent à travailler en équipe. Des professeurs regrettent toutefois qu''il soit impossible de savoir qui, dans le groupe, a vraiment travaillé.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• enthousiaste (adjectif) : hào hứng\n• évaluer (verbe) : đánh giá\n• passif (adjectif) : thụ động\n• une note commune (nom féminin) : điểm chung cả nhóm\n• un carnet de bord (nom masculin) : nhật ký công việc","explications":"• Năm phút đầu của 30 phút chuẩn bị: vấn đề, lập trường, dàn ý. Phần còn lại dành tìm ví dụ.\n• Ghi từ khoá, không viết câu trọn vẹn: trong phòng thi bạn sẽ nói, không đọc.","isPremium":true,"price":19000,"kyNang":"B2-PO-1","vong":"chot","thuTu":5}'::jsonb, '2026-11-15T12:00:04.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh9kjr700d', 'b2po05jrk01x', 1, 'open', 'Écrivez le problème, votre position et l''annonce de votre plan. (40 mots minimum)', '{}'::jsonb, '{"model":"Problème : un projet de groupe peut-il remplacer un examen pour évaluer les étudiants de façon juste ?\nPosition : oui, à condition de prévoir une part d''évaluation individuelle.\nPlan : 1. les avantages du projet (motivation, compétences utiles, lien avec la société) ; 2. le problème de l''évaluation (les étudiants passifs, la note commune) ; 3. des solutions (carnet de bord, oral individuel à la fin du projet)."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2po06jrk01y', 'practice', 'Oral B2 : un plan en deux parties', 'B2', array['Production orale']::text[], 'practice', null, null, '<p>Lisez le document et préparez un plan en deux parties (par exemple : avantages, puis limites ; ou : oui, mais). Notez des mots-clés et un exemple pour chaque idée.</p>', '<p><strong>Des rues sans voitures devant les écoles</strong></p><p>Pour protéger les enfants de la pollution et des accidents, de plus en plus de villes ferment à la circulation les rues situées devant les écoles, à l''heure d''entrée et de sortie des classes. Les parents qui accompagnent leurs enfants à pied s''en félicitent. D''autres, qui travaillent loin et déposent leurs enfants en voiture, se disent pénalisés.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• la circulation (nom féminin) : giao thông\n• se féliciter de (verbe) : hài lòng về\n• pénalisé (adjectif) : bị thiệt\n• un parking relais (nom masculin) : bãi đỗ trung chuyển\n• un aménagement (nom masculin) : sự điều chỉnh","explications":"• Dàn ý hai phần rất hợp với đề « pour ou contre »: phần một một phía, phần hai phía còn lại kèm giải pháp.\n• Mỗi ý một ví dụ: ví dụ là thứ giúp bạn nói được đủ 5 đến 7 phút.","kyNang":"B2-PO-2","vong":"hoc","thuTu":1}'::jsonb, '2026-11-15T12:00:05.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh9kjr700e', 'b2po06jrk01y', 1, 'open', 'Écrivez votre plan : problématique, partie 1, partie 2, conclusion. (60 mots minimum)', '{}'::jsonb, '{"model":"Problématique : faut-il fermer les rues des écoles aux voitures, au risque de compliquer la vie de certains parents ?\nPartie 1, une mesure utile : moins de pollution aux heures de pointe (exemple : l''air devant les écoles près des grands axes) ; plus de sécurité (les enfants traversent sans danger) ; plus d''enfants qui viennent à pied ou à vélo.\nPartie 2, des limites à corriger : parents qui travaillent loin, familles sans transports en commun ; solutions : un parking relais à deux cents mètres, des horaires de fermeture courts.\nConclusion : pour, avec des aménagements."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2po07jrk01z', 'practice', 'Oral B2 : un plan en trois parties', 'B2', array['Production orale']::text[], 'practice', null, null, '<p>Lisez le document et préparez un plan en trois parties (par exemple : constat, causes ou enjeux, solutions). Notez des mots-clés et des exemples.</p>', '<p><strong>Les influenceurs, des journalistes comme les autres ?</strong></p><p>Plusieurs millions de jeunes s''informent aujourd''hui principalement grâce à des influenceurs sur les réseaux sociaux. Contrairement aux journalistes, ceux-ci ne sont tenus à aucune règle de vérification des sources. Un député propose de leur imposer les mêmes obligations qu''aux médias traditionnels.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• s''informer (verbe) : cập nhật tin tức\n• la vérification des sources (nom féminin) : kiểm chứng nguồn\n• imposer (verbe) : áp đặt\n• la transparence (nom féminin) : sự minh bạch\n• l''esprit critique (nom masculin) : tư duy phản biện","explications":"• Ba phần « constat, enjeux, solutions » dùng được cho hầu hết đề xã hội.\n• Phần giải pháp là chỗ thể hiện lập trường riêng: đừng chỉ lặp lại ý của tài liệu.","kyNang":"B2-PO-2","vong":"hoc","thuTu":2}'::jsonb, '2026-11-15T12:00:06.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh9kjr700f', 'b2po07jrk01z', 1, 'open', 'Écrivez votre plan : problématique, trois parties, conclusion. (70 mots minimum)', '{}'::jsonb, '{"model":"Problématique : faut-il imposer aux influenceurs les mêmes règles qu''aux journalistes ?\nPartie 1, le constat : les jeunes s''informent sur les réseaux (exemple : vidéos courtes sur l''actualité) ; influence énorme, parfois plus forte que celle des journaux.\nPartie 2, les risques : fausses informations, publicités cachées (exemple : un produit présenté comme un conseil personnel) ; pas de vérification des sources.\nPartie 3, quelles règles ? Signaler clairement les publicités, citer ses sources, mais ne pas exiger une carte de journaliste ; former les jeunes à l''esprit critique à l''école.\nConclusion : des règles de transparence, oui ; une censure, non."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2po08jrk020', 'practice', 'Oral B2 : un exemple pour chaque idée', 'B2', array['Production orale']::text[], 'practice', null, null, '<p>Voici le plan d''un candidat sur le sujet : « Faut-il ouvrir les magasins le dimanche ? ». Il manque les exemples. Trouvez un exemple précis pour chaque idée.</p>', '<p><strong>Plan du candidat.</strong> Partie 1 : ouvrir le dimanche présente des avantages. Idée 1 : c''est pratique pour les personnes qui travaillent toute la semaine. Idée 2 : cela peut créer des emplois.</p><p>Partie 2 : mais il faut fixer des limites. Idée 3 : le dimanche est un moment important pour la vie de famille. Idée 4 : les petits commerces risquent de ne pas pouvoir suivre.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• des horaires décalés (nom masculin pluriel) : giờ làm lệch ca\n• compatible avec (adjectif) : phù hợp với\n• une zone touristique (nom féminin) : khu du lịch\n• suivre (verbe) : theo kịp\n• une grande surface (nom féminin) : đại siêu thị","explications":"• Ví dụ tốt có người cụ thể, tình huống cụ thể: « une infirmière en horaires décalés » rõ hơn « certaines personnes ».\n• Có thể dùng ví dụ từ đời sống ở Việt Nam: giám khảo đánh giá cao ví dụ cá nhân.","isPremium":true,"price":19000,"kyNang":"B2-PO-2","vong":"hoc","thuTu":3}'::jsonb, '2026-11-15T12:00:07.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh9kjr700g', 'b2po08jrk020', 1, 'open', 'Idée 1 : écrivez un exemple précis. (15 mots minimum)', '{}'::jsonb, '{"model":"Une infirmière qui travaille en horaires décalés du lundi au samedi n''a souvent que le dimanche pour faire ses courses ou acheter des vêtements."}'::jsonb, null), ('qmwh9kjr700h', 'b2po08jrk020', 2, 'open', 'Idée 2 : écrivez un exemple précis. (15 mots minimum)', '{}'::jsonb, '{"model":"Beaucoup d''étudiants cherchent justement un travail le week-end : dans les zones touristiques, l''ouverture du dimanche leur offre des emplois compatibles avec leurs cours."}'::jsonb, null), ('qmwh9kjr700i', 'b2po08jrk020', 3, 'open', 'Idée 3 : écrivez un exemple précis. (15 mots minimum)', '{}'::jsonb, '{"model":"Un vendeur obligé de travailler chaque dimanche ne peut plus déjeuner avec ses enfants ni les accompagner à leurs matchs de football du week-end."}'::jsonb, null), ('qmwh9kjr700j', 'b2po08jrk020', 4, 'open', 'Idée 4 : écrivez un exemple précis. (15 mots minimum)', '{}'::jsonb, '{"model":"Une petite librairie de quartier, tenue par deux personnes, ne peut pas payer un employé de plus le dimanche, alors que la grande surface voisine le peut."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2po09jrk021', 'practice', 'Oral B2 : trente minutes de préparation', 'B2', array['Production orale']::text[], 'practice', null, 30, '<p>Comme à l''examen : vous avez 30 minutes. Lisez le document et préparez votre exposé : problématique, plan détaillé avec des exemples, conclusion. Notez des mots-clés.</p>', '<p><strong>Le tourisme spatial décolle</strong></p><p>Pour quelques centaines de milliers d''euros, des entreprises privées proposent déjà des vols de quelques minutes en apesanteur. Leurs dirigeants promettent que les prix baisseront et que l''espace deviendra une destination comme une autre. Pour les associations écologistes, un seul vol produit autant de CO2 qu''un habitant de la planète en plusieurs années.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• l''apesanteur (nom féminin) : trạng thái không trọng lượng\n• décoller (verbe) : cất cánh\n• un milliardaire (nom masculin) : tỷ phú\n• les émissions (nom féminin pluriel) : lượng khí thải\n• la transition écologique (nom féminin) : chuyển đổi xanh","explications":"• Chia 30 phút: 5 phút vấn đề và lập trường, 15 phút dàn ý và ví dụ, 5 phút mở bài và kết bài, 5 phút đọc lại.\n• Viết sẵn TRỌN câu mở bài và câu kết: đó là hai chỗ dễ lúng túng nhất khi nói.","isPremium":true,"price":19000,"kyNang":"B2-PO-2","vong":"on","thuTu":4}'::jsonb, '2026-11-15T12:00:08.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh9kjr700k', 'b2po09jrk021', 1, 'open', 'Écrivez votre préparation complète. (100 mots minimum)', '{}'::jsonb, '{"model":"Introduction : voyager dans l''espace n''est plus de la science-fiction. Problématique : le tourisme spatial est-il un progrès ou un luxe que la planète ne peut pas se permettre ?\nPartie 1, un rêve et un moteur d''innovation : rêve ancien de l''humanité (premiers pas sur la Lune) ; les entreprises financent une recherche utile ensuite à tous (exemple : satellites, nouveaux matériaux).\nPartie 2, un coût écologique et social : un vol = des années d''émissions d''un habitant ; un loisir réservé à quelques milliardaires pendant que d''autres n''ont pas accès à l''avion.\nPartie 3, ma position : interdire semble difficile, mais on pourrait taxer fortement ces vols et utiliser l''argent pour la transition écologique.\nConclusion : l''espace peut faire rêver, à condition que le prix ne soit pas payé par la planète."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2po10jrk022', 'practice', 'Oral B2 : préparation chronométrée', 'B2', array['Production orale']::text[], 'practice', null, 30, '<p>Nouveau sujet, mêmes conditions : 30 minutes pour préparer votre exposé à partir du document. Problématique, plan détaillé avec des exemples, conclusion.</p>', '<p><strong>Faut-il supprimer les notes à l''école primaire ?</strong></p><p>Dans plusieurs écoles, les enseignants ont remplacé les notes sur 20 par des appréciations en couleurs : vert pour « acquis », orange pour « en cours », rouge pour « non acquis ». Selon eux, les enfants ont moins peur de l''erreur. Certains parents regrettent de ne plus savoir précisément où en est leur enfant par rapport à la classe.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une appréciation (nom féminin) : lời nhận xét\n• acquis (adjectif) : đã nắm được\n• un repère (nom masculin) : mốc, điểm tham chiếu\n• un trimestre (nom masculin) : quý, học kỳ ba tháng\n• classer (verbe) : xếp hạng","explications":"• Bài chốt này đo xem bạn có làm trọn trong 30 phút không: nếu chưa xong, hãy rút ngắn phần ghi chú, đừng rút phần ví dụ.\n• Kết bài bằng một câu ngắn dễ nhớ (« évaluer, oui ; classer, le plus tard possible »): giám khảo nhớ câu cuối.","isPremium":true,"price":19000,"kyNang":"B2-PO-2","vong":"chot","thuTu":5}'::jsonb, '2026-11-15T12:00:09.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh9kjr700l', 'b2po10jrk022', 1, 'open', 'Écrivez votre préparation complète. (100 mots minimum)', '{}'::jsonb, '{"model":"Introduction : à l''école primaire, de plus en plus d''enseignants abandonnent les notes chiffrées. Problématique : peut-on évaluer les enfants sans les noter, sans perdre en clarté pour les familles ?\nPartie 1, les limites des notes : peur de l''erreur, comparaison permanente entre élèves (exemple : un enfant qui se croit « nul » à cause d''un 8 sur 20) ; la note ne dit pas ce qu''il faut améliorer.\nPartie 2, ce que les parents perdent : un repère simple ; difficile de comprendre trois couleurs pour vingt compétences ; inquiétude au moment d''entrer au collège, où les notes reviennent.\nPartie 3, ma proposition : pas de notes avant dix ans, mais un entretien avec les parents chaque trimestre et des commentaires précis sur ce que l''enfant sait faire.\nConclusion : évaluer, oui ; classer, le plus tard possible."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2po11jrk023', 'practice', 'Oral B2 : le travail des robots', 'B2', array['Production orale']::text[], 'practice', null, null, '<p>Lisez le document. À l''examen, vous avez 30 minutes de préparation. Enregistrez votre exposé de 5 à 7 minutes : une introduction avec la problématique, un développement en deux ou trois parties avec des exemples, une conclusion.</p>', '<p><strong>Des robots dans les entrepôts</strong></p><p>Dans un grand entrepôt de logistique près de Lille, des robots transportent désormais les colis à la place des préparateurs de commandes. La direction affirme que les tâches les plus pénibles ont disparu et qu''aucun salarié n''a été licencié. Les syndicats rappellent que l''entreprise n''embauche plus et craignent que l''automatisation ne remplace peu à peu les humains.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un entrepôt (nom masculin) : nhà kho\n• pénible (adjectif) : nặng nhọc\n• licencier (verbe) : sa thải\n• embaucher (verbe) : tuyển dụng\n• accroître (verbe) : làm tăng","explications":"• Mở bài nói có ba nhịp: một câu về tài liệu, problématique, báo trước dàn ý (« Je parlerai d''abord …, puis …, enfin … »).\n• Khi nói, từ nối phải rõ hơn khi viết: « Premièrement », « Cependant », « Pour conclure » giúp giám khảo theo dõi.","ghiAm":true,"kyNang":"B2-PO-3","vong":"hoc","thuTu":1}'::jsonb, '2026-11-15T12:00:10.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh9kjr800m', 'b2po11jrk023', 1, 'open', 'Présentez votre exposé : dégagez le problème, défendez votre point de vue avec des arguments et des exemples. (5 à 7 minutes)', '{}'::jsonb, '{"model":"Ce document évoque l''arrivée des robots dans un entrepôt près de Lille. Il pose une question qui concerne beaucoup de métiers : les robots vont-ils libérer les travailleurs ou les remplacer ? Je pense qu''ils peuvent être une chance, à condition que les entreprises accompagnent ce changement. Je parlerai d''abord des avantages, puis des risques, et enfin de ce qu''il faudrait faire.\n\nD''abord, les robots peuvent supprimer les tâches les plus dures. Porter des colis lourds toute la journée abîme le dos et les genoux. Mon oncle, qui a travaillé quinze ans dans un entrepôt à Hô Chi Minh-Ville, souffre aujourd''hui de douleurs permanentes. Si une machine fait ce travail, c''est un progrès pour la santé.\n\nCependant, le risque pour l''emploi est réel. Le document le dit bien : personne n''est licencié, mais l''entreprise n''embauche plus. Autrement dit, les emplois disparaissent lentement, sans bruit. Et ce sont souvent les personnes les moins diplômées qui perdent le plus.\n\nC''est pourquoi il faut, selon moi, deux choses. Premièrement, former les salariés pour qu''ils deviennent techniciens ou responsables de ces robots. Deuxièmement, partager les gains : si la productivité augmente, une partie pourrait financer des formations ou réduire le temps de travail.\n\nPour conclure, les robots ne sont ni bons ni mauvais en eux-mêmes. Tout dépend de la manière dont on organise leur arrivée. Si on prépare les travailleurs, ils peuvent nous libérer des tâches pénibles ; si on ne fait rien, ils risquent d''accroître les inégalités."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2po12jrl024', 'practice', 'Oral B2 : consommer local', 'B2', array['Production orale']::text[], 'practice', null, null, '<p>Lisez le document. À l''examen, vous avez 30 minutes de préparation. Enregistrez votre exposé de 5 à 7 minutes : une introduction avec la problématique, un développement en deux ou trois parties avec des exemples, une conclusion.</p>', '<p><strong>Le retour du « manger local »</strong></p><p>Marchés de producteurs, paniers de légumes livrés chaque semaine, applications qui indiquent les fermes voisines : consommer local est à la mode. Pour ses défenseurs, c''est meilleur pour la planète et pour l''économie de la région. Ses critiques rappellent que ces produits sont souvent plus chers et qu''une tomate locale cultivée sous serre chauffée peut polluer davantage qu''une tomate importée.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un producteur (nom masculin) : nhà sản xuất, nông hộ\n• une serre (nom féminin) : nhà kính\n• un intermédiaire (nom masculin) : trung gian\n• de saison (expression) : đúng mùa\n• avoir les moyens (expression) : có điều kiện (tiền)","explications":"• Dùng lại một chi tiết của tài liệu để nuancer (ví dụ quả cà chua nhà kính) cho thấy bạn đã đọc kỹ, khác với tóm tắt.\n• Kết bài nên có một đề xuất cụ thể chứ không chỉ nhắc lại lập trường.","ghiAm":true,"kyNang":"B2-PO-3","vong":"hoc","thuTu":2}'::jsonb, '2026-11-15T12:00:11.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh9kjr800n', 'b2po12jrl024', 1, 'open', 'Présentez votre exposé : dégagez le problème, défendez votre point de vue avec des arguments et des exemples. (5 à 7 minutes)', '{}'::jsonb, '{"model":"Le document parle de la mode du « manger local ». La question qu''il pose est la suivante : consommer local est-il vraiment la meilleure solution pour la planète et pour les consommateurs ? À mon avis, c''est une bonne habitude, mais ce n''est pas une solution magique. Je présenterai d''abord ses avantages, puis ses limites.\n\nPremièrement, acheter près de chez soi soutient les agriculteurs de la région. Quand j''achète des légumes au marché de mon quartier, l''argent va directement au producteur, sans intermédiaire. Cela permet à de petites fermes de survivre. Ensuite, les produits sont plus frais : ils n''ont pas passé des jours dans un camion ou un bateau, et souvent ils ont plus de goût.\n\nToutefois, il faut nuancer. Le document donne un exemple intéressant : une tomate locale cultivée sous serre chauffée en hiver peut polluer plus qu''une tomate importée d''un pays chaud. Ce qui compte, ce n''est donc pas seulement la distance, mais aussi la saison et la manière de produire. De plus, le prix reste un problème. Une famille modeste ne peut pas toujours payer vingt pour cent de plus pour ses fruits.\n\nEn conclusion, je pense qu''il faut consommer local, mais surtout de saison. Et pour que tout le monde y ait accès, les cantines scolaires et les communes pourraient montrer l''exemple en achetant aux producteurs de la région. Ainsi, le local ne serait pas seulement une mode réservée à ceux qui en ont les moyens."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2po13jrl025', 'practice', 'Oral B2 : l''école à la maison', 'B2', array['Production orale']::text[], 'practice', null, null, '<p>Lisez le document. À l''examen, vous avez 30 minutes de préparation. Enregistrez votre exposé de 5 à 7 minutes : une introduction avec la problématique, un développement en deux ou trois parties avec des exemples, une conclusion.</p>', '<p><strong>Apprendre sans aller à l''école</strong></p><p>Le nombre de familles qui choisissent d''instruire leurs enfants à la maison a fortement augmenté ces dernières années. Certains parents veulent adapter le rythme à leur enfant, d''autres le protéger du harcèlement. Le gouvernement, lui, souhaite limiter cette pratique : selon lui, l''école est aussi un lieu où l''on apprend à vivre avec les autres.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• instruire (verbe) : dạy dỗ, giáo dục\n• le harcèlement (nom masculin) : bắt nạt, quấy rối\n• irremplaçable (adjectif) : không thể thay thế\n• un milieu (nom masculin) : môi trường, tầng lớp\n• un contrôle (nom masculin) : sự kiểm tra","explications":"• Cặp « D''un côté … D''un autre côté … » giúp trình bày hai phía rõ ràng khi nói.\n• Ví dụ từ người quen (« une amie de ma sœur ») là ví dụ hợp lệ ở phần thi nói, miễn cụ thể và đúng chủ đề.","ghiAm":true,"kyNang":"B2-PO-3","vong":"hoc","thuTu":3}'::jsonb, '2026-11-15T12:00:12.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh9kjr800o', 'b2po13jrl025', 1, 'open', 'Présentez votre exposé : dégagez le problème, défendez votre point de vue avec des arguments et des exemples. (5 à 7 minutes)', '{}'::jsonb, '{"model":"Ce document traite de l''instruction à la maison, une pratique de plus en plus fréquente. Il soulève une question délicate : les parents doivent-ils être libres d''instruire eux-mêmes leurs enfants, ou l''école doit-elle rester obligatoire pour tous ? Je pense que l''école à la maison peut être justifiée dans certains cas, mais qu''elle doit rester une exception. Je vais d''abord expliquer pourquoi certaines familles la choisissent, puis pourquoi l''école reste irremplaçable.\n\nD''un côté, on comprend ces parents. Un enfant victime de harcèlement peut vivre l''école comme un enfer. Une amie de ma sœur a dû quitter son collège après des mois de moqueries ; pendant un an, elle a suivi des cours à distance, et elle a retrouvé confiance en elle. De même, un enfant malade ou qui pratique un sport à haut niveau a besoin d''un rythme particulier.\n\nD''un autre côté, l''école n''est pas seulement un lieu où l''on apprend les mathématiques ou le français. C''est là qu''on rencontre des enfants différents, d''autres milieux, d''autres opinions. On apprend à travailler en groupe, à respecter des règles communes, à gérer les conflits. Et tous les parents n''ont pas le temps ni les compétences pour enseigner toutes les matières.\n\nEn somme, je suis favorable à une solution équilibrée : autoriser l''école à la maison pour des raisons sérieuses, mais avec des contrôles réguliers par des enseignants. Ainsi, on protège à la fois la liberté des familles et le droit de chaque enfant à une éducation complète et ouverte sur les autres."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2po14jrl026', 'practice', 'Oral B2 : la sédentarité', 'B2', array['Production orale']::text[], 'practice', null, null, '<p>Lisez le document. À l''examen, vous avez 30 minutes de préparation. Enregistrez votre exposé de 5 à 7 minutes : une introduction avec la problématique, un développement en deux ou trois parties avec des exemples, une conclusion.</p>', '<p><strong>Assis toute la journée</strong></p><p>Selon une enquête menée dans une grande ville, les adultes passent en moyenne plus de huit heures par jour assis : au bureau, dans les transports, devant la télévision. Les médecins parlent d''un problème de santé publique. Certaines entreprises installent des bureaux debout et organisent des pauses sportives ; d''autres estiment que la santé des salariés relève de leur vie privée.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• la sédentarité (nom féminin) : lối sống ít vận động\n• anodin (adjectif) : vô hại, không đáng kể\n• une intrusion (nom féminin) : sự xâm phạm\n• relever de (verbe) : thuộc về (phạm vi)\n• frappant (adjectif) : gây ấn tượng mạnh","explications":"• Dàn ý ba phần « nguy cơ, vai trò tổ chức, vai trò cá nhân » hợp với đề hỏi « trách nhiệm của ai ».\n• Câu nhượng bộ ngay trong một phần (« Bien sûr, il ne faut pas obliger … ») cho thấy suy nghĩ có sắc thái.","ghiAm":true,"isPremium":true,"price":19000,"kyNang":"B2-PO-3","vong":"hoc","thuTu":4}'::jsonb, '2026-11-15T12:00:13.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh9kjr800p', 'b2po14jrl026', 1, 'open', 'Présentez votre exposé : dégagez le problème, défendez votre point de vue avec des arguments et des exemples. (5 à 7 minutes)', '{}'::jsonb, '{"model":"Le document présente un chiffre frappant : beaucoup d''adultes passent plus de huit heures par jour assis. Il pose la question de la responsabilité : lutter contre la sédentarité, est-ce l''affaire de chacun, ou les entreprises doivent-elles aussi agir ? Selon moi, la responsabilité est partagée. J''expliquerai d''abord pourquoi la sédentarité est un vrai danger, puis quel rôle peuvent jouer les entreprises, et enfin ce que chacun peut faire.\n\nTout d''abord, rester assis trop longtemps n''est pas anodin. Les médecins font le lien avec les maladies du cœur, le diabète ou les douleurs de dos. Moi-même, quand je prépare un examen, je peux rester six heures devant mon ordinateur, et le soir j''ai mal au cou et je dors mal.\n\nEnsuite, les entreprises ont intérêt à agir. Un salarié en bonne santé est moins souvent absent et plus concentré. Des bureaux qui permettent de travailler debout, des réunions en marchant, ou une salle de sport accessible, ce n''est pas très cher. Bien sûr, il ne faut pas obliger les salariés à faire du sport : ce serait une intrusion dans leur vie privée. Mais on peut leur en donner la possibilité.\n\nEnfin, chacun peut changer de petites habitudes : prendre l''escalier, descendre du bus un arrêt plus tôt, se lever toutes les heures.\n\nPour conclure, la sédentarité est un problème collectif qui demande des réponses à plusieurs niveaux. L''entreprise peut créer de bonnes conditions, mais c''est finalement à chacun de bouger."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2po15jrl027', 'practice', 'Oral B2 : vivre seul', 'B2', array['Production orale']::text[], 'practice', null, null, '<p>Lisez le document. À l''examen, vous avez 30 minutes de préparation. Enregistrez votre exposé de 5 à 7 minutes : une introduction avec la problématique, un développement en deux ou trois parties avec des exemples, une conclusion.</p>', '<p><strong>De plus en plus de personnes vivent seules</strong></p><p>Dans les grandes villes européennes, près d''un logement sur deux est aujourd''hui occupé par une seule personne. Pour certains, vivre seul est un choix synonyme de liberté. Pour d''autres, c''est une situation subie qui peut mener à l''isolement, en particulier chez les personnes âgées. Des projets d''habitat partagé entre générations voient le jour.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• subir (verbe) : chịu đựng (không chọn)\n• l''isolement (nom masculin) : sự cô lập\n• un conjoint (nom masculin) : vợ / chồng\n• l''habitat partagé (nom masculin) : nhà ở chung\n• autonome (adjectif) : tự lập","explications":"• Phân biệt hai khái niệm gần nhau (vivre seul, la solitude) ngay ở mở bài là cách hay để đặt vấn đề có chiều sâu.\n• Ví dụ đối xứng (một người trẻ, một người già) làm hai phần cân đối.","ghiAm":true,"isPremium":true,"price":19000,"kyNang":"B2-PO-3","vong":"hoc","thuTu":5}'::jsonb, '2026-11-15T12:00:14.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh9kjr800q', 'b2po15jrl027', 1, 'open', 'Présentez votre exposé : dégagez le problème, défendez votre point de vue avec des arguments et des exemples. (5 à 7 minutes)', '{}'::jsonb, '{"model":"Ce document évoque une évolution importante : de plus en plus de personnes vivent seules. La question est de savoir si c''est le signe d''une plus grande liberté ou d''un isolement croissant. À mon avis, vivre seul n''est pas un problème en soi ; le problème, c''est la solitude qu''on n''a pas choisie. Je parlerai d''abord du choix de vivre seul, ensuite du risque d''isolement, et je terminerai par des solutions.\n\nPour beaucoup de jeunes, vivre seul est une étape positive. On organise son temps comme on veut, on apprend à être autonome. Quand j''ai quitté la maison de mes parents pour étudier, avoir mon petit studio m''a appris à gérer un budget et à prendre des décisions seule.\n\nMais pour d''autres, cette situation est subie. Une personne âgée qui a perdu son conjoint, dont les enfants habitent loin, peut passer des journées entières sans parler à personne. Dans mon immeuble, une voisine de quatre-vingts ans m''a dit un jour que le facteur était la seule personne qu''elle voyait certains jours. Cette solitude a des conséquences sur la santé physique et morale.\n\nC''est pourquoi les projets d''habitat partagé me semblent très intéressants. Par exemple, un étudiant peut être logé gratuitement chez une personne âgée en échange de sa présence et de petits services. Les deux y gagnent : le jeune économise un loyer, la personne âgée se sent moins seule.\n\nEn conclusion, il faut respecter le choix de vivre seul, tout en créant des liens pour ceux qui n''ont pas choisi la solitude."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2po16jrl028', 'practice', 'Oral B2 : la langue française dans le monde', 'B2', array['Production orale']::text[], 'practice', null, null, '<p>Lisez le document. À l''examen, vous avez 30 minutes de préparation. Enregistrez votre exposé de 5 à 7 minutes : une introduction avec la problématique, un développement en deux ou trois parties avec des exemples, une conclusion.</p>', '<p><strong>Le français, langue d''avenir ?</strong></p><p>Le nombre de francophones dans le monde augmente, surtout grâce à la croissance démographique en Afrique. Pourtant, dans les organisations internationales et dans la recherche scientifique, l''anglais domine de plus en plus. Certains jugent inutile de défendre le français ; d''autres y voient un enjeu de diversité culturelle.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un francophone (nom masculin) : người nói tiếng Pháp\n• la croissance démographique (nom féminin) : tăng dân số\n• dominer (verbe) : chiếm ưu thế\n• un atout (nom masculin) : lợi thế\n• le plurilinguisme (nom masculin) : sự đa ngữ","explications":"• Đề có tính cá nhân (bạn đang học tiếng Pháp) thì nói thẳng vị trí của mình, nhưng vẫn phải lập luận chứ không chỉ bày tỏ cảm xúc.\n• Thừa nhận ý của phe kia (« Il faut reconnaître que … ») trước khi phản bác làm bài thuyết phục hơn.","ghiAm":true,"isPremium":true,"price":19000,"kyNang":"B2-PO-3","vong":"hoc","thuTu":6}'::jsonb, '2026-11-15T12:00:15.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh9kjr800r', 'b2po16jrl028', 1, 'open', 'Présentez votre exposé : dégagez le problème, défendez votre point de vue avec des arguments et des exemples. (5 à 7 minutes)', '{}'::jsonb, '{"model":"Le document présente une situation paradoxale : il y a de plus en plus de francophones, mais l''anglais domine dans les institutions et dans la science. Faut-il encore défendre et apprendre le français dans un monde dominé par l''anglais ? En tant qu''apprenant de français, je réponds évidemment oui, mais je vais essayer de le justifier. Je parlerai d''abord de la place de l''anglais, puis des raisons de défendre le français.\n\nIl faut reconnaître que l''anglais est devenu la langue commune du commerce, d''internet et de la recherche. Ma cousine, qui est chercheuse en biologie, publie tous ses articles en anglais, et elle n''a pas vraiment le choix. Refuser l''anglais serait irréaliste.\n\nPourtant, une langue n''est pas seulement un outil de communication. Elle porte une culture, une manière de penser, une littérature, un cinéma. Si tout le monde ne parle qu''une seule langue, on perd cette diversité. De plus, le français reste une langue d''avenir, notamment grâce à l''Afrique, où la population jeune grandit rapidement. Pour un Vietnamien, parler français ouvre aussi des portes : des études en France ou au Canada, et des relations avec de nombreux pays.\n\nEnfin, apprendre le français n''empêche pas de parler anglais. Au contraire, connaître plusieurs langues est un atout sur le marché du travail.\n\nPour conclure, je pense que l''avenir n''est pas à une langue unique, mais au plurilinguisme. Défendre le français, ce n''est pas lutter contre l''anglais, c''est défendre la diversité du monde."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2po17jrl029', 'practice', 'Oral B2 : un sujet surprise B2', 'B2', array['Production orale']::text[], 'practice', null, null, '<p>Sujet surprise : lisez le document, préparez-vous rapidement (10 minutes pour vous entraîner, 30 minutes à l''examen), puis enregistrez votre exposé de 5 minutes environ.</p>', '<p><strong>Coder dès l''école primaire ?</strong></p><p>Plusieurs pays ont rendu obligatoire l''apprentissage de la programmation informatique dès l''âge de huit ans. Leurs gouvernements estiment que coder sera aussi indispensable que lire et compter. Des enseignants répondent que les élèves manquent déjà de temps pour les apprentissages de base et que les écrans sont assez présents dans la vie des enfants.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• la programmation (nom féminin) : lập trình\n• indispensable (adjectif) : không thể thiếu\n• la persévérance (nom féminin) : sự kiên trì\n• décomposer (verbe) : chia nhỏ\n• intégrer à (verbe) : lồng vào","explications":"• Đề bất ngờ: dùng ngay khuôn quen « pour, inquiétudes, giải pháp », không cần dàn ý sáng tạo.\n• Nếu thiếu ví dụ, nghĩ tới người thân, trường học, thành phố của mình.","ghiAm":true,"isPremium":true,"price":19000,"kyNang":"B2-PO-3","vong":"on","thuTu":7}'::jsonb, '2026-11-15T12:00:16.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh9kjr800s', 'b2po17jrl029', 1, 'open', 'Présentez votre exposé sur ce sujet surprise. (5 minutes environ)', '{}'::jsonb, '{"model":"Ce document pose une question liée à l''avenir de l''école : faut-il apprendre à programmer aux enfants dès l''école primaire ? Je pense que oui, mais sans écran au début et sans sacrifier les bases. Je présenterai d''abord les arguments pour, puis les inquiétudes des enseignants, avant de proposer une solution.\n\nD''abord, le numérique est partout dans notre vie. Comprendre comment fonctionne un programme aide à ne pas être seulement un consommateur passif d''applications. De plus, apprendre à coder développe la logique et la persévérance : quand un programme ne marche pas, il faut chercher l''erreur, recommencer, essayer autre chose. Mon petit frère a suivi un atelier de programmation l''été dernier, et il a appris à décomposer un problème en petites étapes, ce qui l''aide aussi en mathématiques.\n\nCependant, les enseignants ont raison sur deux points. Le temps scolaire est limité, et lire, écrire et compter restent prioritaires. Par ailleurs, les enfants passent déjà beaucoup de temps devant les écrans.\n\nC''est pourquoi on pourrait commencer la programmation sans ordinateur, avec des jeux, des cartes ou de petits robots, et l''intégrer aux mathématiques plutôt que de créer une matière de plus.\n\nEn conclusion, coder peut devenir une compétence de base, à condition de l''enseigner intelligemment."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2po18jrl02a', 'practice', 'Oral B2 : le monologue B2', 'B2', array['Production orale']::text[], 'practice', null, null, '<p>Comme le jour de l''examen : 30 minutes de préparation (chronométrez-vous), puis un exposé de 5 à 7 minutes, enregistré d''une seule traite. Ne lisez pas vos notes : regardez-les seulement.</p>', '<p><strong>Trop de touristes ?</strong></p><p>Venise, Barcelone, la baie d''Hạ Long : certains sites célèbres accueillent chaque année des millions de visiteurs. Plusieurs villes ont instauré des quotas ou des droits d''entrée pour limiter la foule. Les professionnels du tourisme redoutent une baisse de leurs revenus, tandis que des habitants affirment que leur ville est devenue invivable.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• le surtourisme (nom masculin) : quá tải du lịch\n• instaurer (verbe) : thiết lập\n• un droit d''entrée (nom masculin) : phí vào cửa\n• redouter (verbe) : lo sợ\n• répartir (verbe) : phân bổ","explications":"• Ghi âm một lượt không dừng, như trong phòng thi: dừng lâu thì dùng câu nối (« J''en viens maintenant à … ») thay vì im lặng.\n• Nghe lại bản ghi và kiểm: có problématique không, có báo dàn ý không, mỗi phần có ví dụ không, có kết bài không.","ghiAm":true,"isPremium":true,"price":19000,"kyNang":"B2-PO-3","vong":"chot","thuTu":8}'::jsonb, '2026-11-15T12:00:17.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh9kjr800t', 'b2po18jrl02a', 1, 'open', 'Présentez votre exposé : dégagez le problème, défendez votre point de vue avec des arguments et des exemples. (5 à 7 minutes)', '{}'::jsonb, '{"model":"Ce document aborde un phénomène qu''on appelle parfois le surtourisme. Des sites célèbres, comme Venise ou la baie d''Hạ Long, reçoivent tellement de visiteurs que certaines villes veulent limiter leur nombre. Faut-il donc restreindre l''accès aux lieux touristiques, au risque de pénaliser l''économie locale ? Je défendrai l''idée qu''une limitation est nécessaire, à condition qu''elle soit bien pensée. J''évoquerai d''abord les conséquences du tourisme de masse, puis les arguments des professionnels, et enfin les solutions possibles.\n\nPremièrement, le tourisme de masse abîme ce qui attire les touristes. À Hạ Long, les bateaux et les déchets menacent l''eau de la baie. Dans certains quartiers de grandes villes européennes, les logements sont transformés en locations pour touristes, et les habitants, qui ne trouvent plus à se loger, partent. Une ville sans habitants devient un décor, pas une ville.\n\nDeuxièmement, il ne faut pas oublier que des milliers de familles vivent du tourisme : guides, restaurateurs, hôteliers. Mon oncle tient une petite agence à Hội An, et une baisse brutale des visiteurs serait pour lui une catastrophe. On ne peut donc pas simplement fermer les portes.\n\nC''est pourquoi les solutions doivent être progressives. On peut fixer un nombre maximum de visiteurs par jour, avec une réservation en ligne, comme pour certains musées. Le droit d''entrée peut servir à financer la protection du site. Enfin, on peut encourager les touristes à découvrir des lieux moins connus, ce qui répartit les revenus sur tout un territoire.\n\nPour conclure, limiter le tourisme n''est pas être contre le tourisme. C''est au contraire le meilleur moyen de protéger les sites, les habitants et, à long terme, les emplois qui en dépendent."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2po19jrl02b', 'practice', 'Oral B2 : je maintiens que', 'B2', array['Production orale']::text[], 'practice', null, null, '<p>Après l''exposé, l''examinateur discute avec vous et conteste votre point de vue. Lisez la situation, puis enregistrez votre réponse à chaque intervention de l''examinateur (30 secondes à une minute). Restez poli, mais défendez vos idées.</p>', '<p><strong>Situation.</strong> Dans votre exposé, vous avez défendu l''idée que les transports en commun devraient être gratuits dans votre ville. L''examinateur n''est pas d''accord.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• maintenir (verbe) : giữ nguyên (ý kiến)\n• dégrader (verbe) : phá hoại\n• démagogique (adjectif) : mị dân\n• désengorger (verbe) : giảm ùn tắc\n• un ménage (nom masculin) : hộ gia đình","explications":"• Giữ ý kiến lịch sự: « Je comprends votre inquiétude, mais je maintiens que … », « Je ne suis pas convaincu par cet argument ».\n• Mỗi câu đáp: công nhận ngắn, phản bác, một lý do hoặc ví dụ. Ba câu là đủ.","ghiAm":true,"kyNang":"B2-PO-4","vong":"hoc","thuTu":1}'::jsonb, '2026-11-15T12:00:18.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh9kjr800u', 'b2po19jrl02b', 1, 'open', 'Mais qui va payer ? Les impôts vont augmenter pour tout le monde.', '{}'::jsonb, '{"model":"Je comprends votre inquiétude, mais je maintiens que c''est une bonne mesure. Les tickets ne couvrent souvent qu''une petite partie du coût réel des transports. Le reste est déjà payé par les impôts. On pourrait financer la différence par une taxe sur les grandes entreprises, qui profitent aussi de salariés qui arrivent à l''heure."}'::jsonb, null), ('qmwh9kjr800v', 'b2po19jrl02b', 2, 'open', 'Les gens ne respectent pas ce qui est gratuit. Les bus seront sales et abîmés.', '{}'::jsonb, '{"model":"Je ne suis pas convaincu par cet argument. Les parcs publics et les bibliothèques sont gratuits, et la plupart des gens les respectent. Il y aura toujours quelques personnes qui dégradent, avec ou sans ticket. La solution, c''est d''avoir du personnel dans les bus, pas de faire payer tout le monde."}'::jsonb, null), ('qmwh9kjr800w', 'b2po19jrl02b', 3, 'open', 'Ceux qui ont une voiture ne la laisseront pas au garage, même si le bus est gratuit.', '{}'::jsonb, '{"model":"C''est vrai pour une partie des automobilistes, je le reconnais. Mais pour d''autres, le prix compte vraiment, surtout pour une famille de quatre personnes. Et la gratuité doit s''accompagner de bus plus fréquents. Si le bus passe toutes les cinq minutes, beaucoup de gens changeront leurs habitudes."}'::jsonb, null), ('qmwh9kjr800x', 'b2po19jrl02b', 4, 'open', 'Vous ne trouvez pas que c''est une mesure démagogique, juste pour plaire aux électeurs ?', '{}'::jsonb, '{"model":"Non, je ne le pense pas. Une mesure populaire n''est pas forcément démagogique. Ici, il y a des objectifs concrets : réduire la pollution, désengorger le centre-ville et aider les ménages modestes. Ce qui compte, c''est de mesurer les résultats après deux ou trois ans, et de corriger si nécessaire."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2po20jrl02c', 'practice', 'Oral B2 : vous avez raison, mais', 'B2', array['Production orale']::text[], 'practice', null, null, '<p>Après l''exposé, l''examinateur discute avec vous et conteste votre point de vue. Lisez la situation, puis enregistrez votre réponse à chaque intervention de l''examinateur (30 secondes à une minute). Restez poli, mais défendez vos idées.</p>', '<p><strong>Situation.</strong> Vous avez soutenu que les devoirs à la maison devraient être supprimés au collège. L''examinateur vous oppose plusieurs arguments. Pour chacun, reconnaissez ce qui est juste, puis réfutez.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• réfuter (verbe) : bác bỏ\n• désavantagé (adjectif) : bị thiệt thòi\n• légitime (adjectif) : chính đáng\n• un carnet de suivi (nom masculin) : sổ theo dõi\n• le bien-être (nom masculin) : sự khoẻ mạnh, hạnh phúc","explications":"• Mẫu nhượng bộ khi nói: « Vous avez raison sur un point, mais … », « Je suis d''accord, toutefois … », « C''est légitime. Cela dit, … ».\n• Phần « mais » phải nặng hơn phần công nhận, nếu không giám khảo nghĩ bạn đã đổi ý.","ghiAm":true,"kyNang":"B2-PO-4","vong":"hoc","thuTu":2}'::jsonb, '2026-11-15T12:00:19.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh9kjr800y', 'b2po20jrl02c', 1, 'open', 'Sans devoirs, les élèves ne révisent plus rien.', '{}'::jsonb, '{"model":"Vous avez raison sur un point : il faut réviser pour retenir. Mais rien n''empêche de le faire en classe, avec le professeur. Des temps d''étude encadrés à la fin de la journée permettraient de réviser sans que les élèves qui n''ont pas d''aide à la maison soient désavantagés."}'::jsonb, null), ('qmwh9kjr800z', 'b2po20jrl02c', 2, 'open', 'Les devoirs apprennent l''autonomie.', '{}'::jsonb, '{"model":"Je suis d''accord, l''autonomie est essentielle. Toutefois, les devoirs ne la développent pas toujours. Souvent, ce sont les parents qui aident, ou même qui font l''exercice. On peut apprendre l''autonomie autrement, par exemple avec des projets personnels ou des lectures choisies librement."}'::jsonb, null), ('qmwh9kjr8010', 'b2po20jrl02c', 3, 'open', 'Les parents veulent savoir ce que font leurs enfants à l''école.', '{}'::jsonb, '{"model":"C''est tout à fait légitime. Cela dit, les devoirs ne sont pas le seul moyen de les informer. Un carnet de suivi en ligne, des réunions régulières ou une présentation des projets en fin de trimestre donnent une image plus juste de ce que l''enfant apprend."}'::jsonb, null), ('qmwh9kjr8011', 'b2po20jrl02c', 4, 'open', 'Dans certains pays d''Asie, les élèves font beaucoup de devoirs et ils obtiennent d''excellents résultats.', '{}'::jsonb, '{"model":"Il est vrai que leurs résultats aux évaluations internationales sont très bons. Pour autant, ces systèmes ont aussi un coût : beaucoup d''élèves sont épuisés et stressés, je le sais bien, car au Vietnam les cours du soir sont fréquents. Les résultats ne disent pas tout du bien-être des enfants."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2po21jrl02d', 'practice', 'Oral B2 : que voulez-vous dire ?', 'B2', array['Production orale']::text[], 'practice', null, null, '<p>Après l''exposé, l''examinateur discute avec vous et conteste votre point de vue. Lisez la situation, puis enregistrez votre réponse à chaque intervention de l''examinateur (30 secondes à une minute). Restez poli, mais défendez vos idées.</p>', '<p><strong>Situation.</strong> Vous avez présenté le télétravail comme un progrès. Les questions de l''examinateur sont parfois vagues ou difficiles. Avant de répondre, demandez une précision, reformulez ou prenez poliment le temps de réfléchir.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• le désengagement (nom masculin) : sự giảm gắn bó\n• reformuler (verbe) : diễn đạt lại\n• nuire à (verbe) : gây hại cho\n• mesurable (adjectif) : đo được\n• nettement (adverbe) : rõ rệt","explications":"• Hỏi lại không bị trừ điểm, còn được tính là kỹ năng tương tác: « Qu''entendez-vous par … ? », « Pourriez-vous préciser ? ».\n• Câu giờ lịch sự thay cho im lặng: « C''est une question difficile, laissez-moi réfléchir un instant », « Si je comprends bien, vous me demandez si … ».","ghiAm":true,"kyNang":"B2-PO-4","vong":"hoc","thuTu":3}'::jsonb, '2026-11-15T12:00:20.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh9kjr8012', 'b2po21jrl02d', 1, 'open', 'Le télétravail, ce n''est pas une forme de désengagement ?', '{}'::jsonb, '{"model":"Excusez-moi, qu''entendez-vous exactement par « désengagement » ? Vous voulez dire que les salariés se sentent moins liés à leur entreprise ? Si c''est le cas, je pense que ce risque existe, mais il dépend surtout de l''organisation : avec deux jours au bureau par semaine, le lien avec l''équipe reste fort."}'::jsonb, null), ('qmwh9kjr8013', 'b2po21jrl02d', 2, 'open', 'Et le collectif, alors ?', '{}'::jsonb, '{"model":"Si je comprends bien, vous me demandez si le télétravail nuit à l''esprit d''équipe. C''est une vraie question. Je dirais que le collectif ne disparaît pas, il change de forme : les réunions doivent être mieux préparées, et les moments passés ensemble au bureau deviennent plus importants."}'::jsonb, null), ('qmwh9kjr8014', 'b2po21jrl02d', 3, 'open', 'Selon vous, la productivité d''un salarié est-elle vraiment mesurable quand il travaille à distance ?', '{}'::jsonb, '{"model":"C''est une question difficile, laissez-moi réfléchir un instant. Je crois qu''on ne peut pas mesurer la productivité seulement en heures passées devant l''écran. En revanche, on peut évaluer les résultats : un rapport terminé, un client satisfait, un projet livré à temps. Le télétravail oblige justement à fixer des objectifs plus clairs."}'::jsonb, null), ('qmwh9kjr8015', 'b2po21jrl02d', 4, 'open', 'Vous dites que c''est bon pour l''environnement. Vous en êtes sûr ?', '{}'::jsonb, '{"model":"Pourriez-vous préciser ce qui vous fait douter ? Si vous pensez à la consommation d''énergie à la maison, c''est vrai qu''elle augmente un peu. Mais, dans l''ensemble, éviter deux heures de trajet en voiture par jour réduit nettement la pollution, surtout dans les grandes villes."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2po22jrl02e', 'practice', 'Oral B2 : tout dépend de', 'B2', array['Production orale']::text[], 'practice', null, null, '<p>Après l''exposé, l''examinateur discute avec vous et conteste votre point de vue. Lisez la situation, puis enregistrez votre réponse à chaque intervention de l''examinateur (30 secondes à une minute). Restez poli, mais défendez vos idées.</p>', '<p><strong>Situation.</strong> Vous avez parlé des réseaux sociaux. L''examinateur vous pousse vers des positions extrêmes. Répondez en nuançant : évitez « toujours », « jamais », « tous ».</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• nuancer (verbe) : nói có sắc thái\n• contourner (verbe) : lách, né\n• généraliser (verbe) : khái quát hoá\n• dans une certaine mesure (expression) : ở một mức độ nào đó\n• exagéré (adjectif) : phóng đại","explications":"• Từ làm mềm câu: « tout dépend de », « pas forcément », « dans une certaine mesure », « plutôt », « ce serait exagéré de dire que ».\n• Giám khảo cố ý đẩy bạn tới cực đoan để xem bạn có biết nói có sắc thái không: đây là tiêu chí của B2.","ghiAm":true,"isPremium":true,"price":19000,"kyNang":"B2-PO-4","vong":"hoc","thuTu":4}'::jsonb, '2026-11-15T12:00:21.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh9kjr8016', 'b2po22jrl02e', 1, 'open', 'Donc, pour vous, les réseaux sociaux sont dangereux pour les jeunes ?', '{}'::jsonb, '{"model":"Je ne dirais pas cela de façon aussi générale. Tout dépend de l''usage qu''on en fait. Un adolescent qui passe cinq heures par jour à comparer sa vie à celle des autres, oui, cela peut être dangereux. Mais les réseaux permettent aussi de garder le contact avec des amis ou d''apprendre des choses."}'::jsonb, null), ('qmwh9kjr8017', 'b2po22jrl02e', 2, 'open', 'Alors il faudrait les interdire aux moins de quinze ans ?', '{}'::jsonb, '{"model":"Pas forcément. Une interdiction totale serait difficile à contrôler, et les jeunes trouveraient facilement un moyen de la contourner. Il me semble plus réaliste de limiter certaines fonctions, comme les messages avec des inconnus, et surtout d''éduquer les enfants à un usage raisonnable, à l''école et en famille."}'::jsonb, null), ('qmwh9kjr8018', 'b2po22jrl02e', 3, 'open', 'De toute façon, tous les influenceurs mentent, non ?', '{}'::jsonb, '{"model":"Non, je ne pense pas qu''on puisse généraliser. Certains influenceurs font de la publicité cachée, c''est vrai. D''autres, en revanche, expliquent des sujets scientifiques ou partagent des recettes avec beaucoup de sérieux. Dans une certaine mesure, c''est au public d''apprendre à faire la différence."}'::jsonb, null), ('qmwh9kjr8019', 'b2po22jrl02e', 4, 'open', 'Les réseaux sociaux ont détruit l''amitié, vous ne trouvez pas ?', '{}'::jsonb, '{"model":"Ce serait un peu exagéré de dire cela. Ils ont plutôt changé la manière de vivre l''amitié. Personnellement, je garde contact grâce à eux avec des amis partis étudier à l''étranger. Le risque, c''est de remplacer les rencontres réelles par des messages ; il faut donc trouver un équilibre."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2po23jrl02f', 'practice', 'Oral B2 : et pourtant', 'B2', array['Production orale']::text[], 'practice', null, null, '<p>Après l''exposé, l''examinateur discute avec vous et conteste votre point de vue. Lisez la situation, puis enregistrez votre réponse à chaque intervention de l''examinateur (30 secondes à une minute). Restez poli, mais défendez vos idées.</p>', '<p><strong>Situation.</strong> Vous avez défendu la voiture électrique comme une solution pour l''environnement. L''examinateur vous oppose des contre-exemples. Reconnaissez le fait, puis montrez qu''il ne remet pas en cause votre position (ou seulement en partie).</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un contre-exemple (nom masculin) : phản ví dụ\n• nier (verbe) : phủ nhận\n• remettre en cause (expression) : đặt lại vấn đề\n• une borne de recharge (nom féminin) : trạm sạc\n• rejeter (verbe) : thải ra","explications":"• Ba cách xử lý phản ví dụ: đó là trường hợp riêng (« l''exception ne fait pas la règle »), đó là vấn đề có thể sửa, hoặc công nhận và điều chỉnh lập trường một phần.\n• Điều chỉnh lập trường (« cela m''oblige à nuancer ma position ») không phải thua: đó là dấu hiệu của người tranh luận trưởng thành.","ghiAm":true,"isPremium":true,"price":19000,"kyNang":"B2-PO-4","vong":"hoc","thuTu":5}'::jsonb, '2026-11-15T12:00:22.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh9kjr801a', 'b2po23jrl02f', 1, 'open', 'Les batteries demandent des métaux extraits dans des conditions terribles.', '{}'::jsonb, '{"model":"C''est un problème réel, je ne le nie pas. Mais il ne remet pas en cause l''idée elle-même : il montre qu''il faut contrôler la production. On peut exiger des entreprises qu''elles respectent les droits des travailleurs et développer le recyclage des batteries pour extraire moins de métaux."}'::jsonb, null), ('qmwh9kjr801b', 'b2po23jrl02f', 2, 'open', 'Mon voisin a acheté une voiture électrique et il ne peut presque jamais la recharger près de chez lui.', '{}'::jsonb, '{"model":"Votre voisin a raison de se plaindre, mais c''est un cas qui montre un retard d''équipement, pas un défaut de la voiture électrique. L''exception ne fait pas la règle : dans beaucoup de villes, les bornes se multiplient. C''est justement aux communes d''accélérer leur installation."}'::jsonb, null), ('qmwh9kjr801c', 'b2po23jrl02f', 3, 'open', 'Dans un pays où l''électricité vient du charbon, la voiture électrique pollue aussi.', '{}'::jsonb, '{"model":"Vous avez raison, et c''est un point important. Dans ce cas, le gain pour le climat est plus faible. Pourtant, même là, la voiture électrique ne rejette rien dans la rue, ce qui améliore l''air des villes. Et la vraie solution est de changer en même temps la production d''électricité."}'::jsonb, null), ('qmwh9kjr801d', 'b2po23jrl02f', 4, 'open', 'Une voiture électrique coûte beaucoup plus cher : ce n''est pas pour tout le monde.', '{}'::jsonb, '{"model":"Pour l''instant, c''est vrai, et cela m''oblige à nuancer ma position. La voiture électrique ne suffit pas, il faut aussi développer les transports en commun et le vélo. Mais le prix baisse chaque année, et des aides publiques pourraient la rendre accessible aux ménages modestes."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2po24jrm02g', 'practice', 'Oral B2 : revenons au sujet', 'B2', array['Production orale']::text[], 'practice', null, null, '<p>Après l''exposé, l''examinateur discute avec vous et conteste votre point de vue. Lisez la situation, puis enregistrez votre réponse à chaque intervention de l''examinateur (30 secondes à une minute). Restez poli, mais défendez vos idées.</p>', '<p><strong>Situation.</strong> Votre exposé portait sur la question : « Faut-il interdire les panneaux publicitaires dans les rues ? ». Vous étiez pour. L''examinateur s''éloigne du sujet. Répondez brièvement, puis ramenez poliment la discussion vers la question de départ.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un panneau publicitaire (nom masculin) : biển quảng cáo\n• l''espace public (nom masculin) : không gian công cộng\n• s''éloigner de (verbe) : đi xa khỏi\n• rejoindre (verbe) : gặp, liên quan tới\n• si vous le permettez (expression) : nếu ông / bà cho phép","explications":"• Đáp ngắn câu lạc đề rồi kéo về: « Mais pour revenir à notre sujet, … », « Cela dit, votre question rejoint notre sujet », « Si vous le permettez, je voudrais revenir à … ».\n• Đừng từ chối trả lời: một câu ngắn lịch sự rồi mới quay về.","ghiAm":true,"isPremium":true,"price":19000,"kyNang":"B2-PO-4","vong":"hoc","thuTu":6}'::jsonb, '2026-11-15T12:00:23.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh9kjr801e', 'b2po24jrm02g', 1, 'open', 'Et la publicité à la télévision, vous la regardez ?', '{}'::jsonb, '{"model":"Comme tout le monde, il m''arrive d''en voir. Mais la différence, c''est qu''à la télévision je peux changer de chaîne ou éteindre. Dans la rue, on ne choisit pas : c''est justement pour cela que je pense qu''il faut limiter les panneaux publicitaires dans l''espace public."}'::jsonb, null), ('qmwh9kjr801f', 'b2po24jrm02g', 2, 'open', 'D''ailleurs, vous passez beaucoup de temps sur votre téléphone ?', '{}'::jsonb, '{"model":"Sans doute plus que je ne le voudrais, je l''avoue ! Mais pour revenir à notre sujet, les écrans publicitaires géants dans les rues posent un autre problème : ils consomment beaucoup d''électricité, jour et nuit, et ils imposent leurs images à tous les passants."}'::jsonb, null), ('qmwh9kjr801g', 'b2po24jrm02g', 3, 'open', 'Parlons de la mode en général : vous suivez les tendances ?', '{}'::jsonb, '{"model":"Pas vraiment, je suis plutôt fidèle aux mêmes vêtements. Cela dit, votre question rejoint notre sujet : la publicité dans la rue pousse justement à suivre les tendances et à acheter toujours plus. C''est l''une des raisons pour lesquelles je souhaite qu''elle soit limitée."}'::jsonb, null), ('qmwh9kjr801h', 'b2po24jrm02g', 4, 'open', 'Vous avez parlé d''environnement. Que pensez-vous de l''énergie nucléaire ?', '{}'::jsonb, '{"model":"C''est un débat passionnant, mais il nous éloignerait un peu de la question. Si vous le permettez, je voudrais revenir aux panneaux publicitaires : ma position, c''est qu''en les réduisant, une ville peut à la fois économiser de l''énergie et rendre ses rues plus agréables."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2po25jrm02h', 'practice', 'Oral B2 : défendez votre position', 'B2', array['Production orale']::text[], 'practice', null, null, '<p>Après l''exposé, l''examinateur discute avec vous et conteste votre point de vue. Lisez la situation, puis enregistrez votre réponse à chaque intervention de l''examinateur (30 secondes à une minute). Restez poli, mais défendez vos idées.</p>', '<p><strong>Situation.</strong> Vous avez défendu l''idée que les cirques ne devraient plus présenter d''animaux sauvages. L''examinateur mélange tous les types d''interventions : objection, question floue, contre-exemple, digression, provocation.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• l''attachement (nom masculin) : sự gắn bó\n• une troupe (nom féminin) : đoàn (nghệ thuật)\n• ses semblables (nom masculin pluriel) : đồng loại\n• une remorque (nom féminin) : xe moóc\n• une espèce menacée (nom féminin) : loài bị đe doạ","explications":"• Nhận diện loại câu trước khi đáp: phản bác (giữ ý), câu mơ hồ (làm rõ), phản ví dụ (trường hợp riêng), lạc đề (kéo về), khiêu khích (nói có sắc thái).\n• Câu khiêu khích « avec votre raisonnement, il faudrait aussi … » thường là cái bẫy: đừng nhận hết, hãy phân biệt.","ghiAm":true,"isPremium":true,"price":19000,"kyNang":"B2-PO-4","vong":"on","thuTu":7}'::jsonb, '2026-11-15T12:00:24.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh9kjr801i', 'b2po25jrm02h', 1, 'open', 'Le cirque avec des animaux, c''est une tradition. Vous voulez supprimer une partie de notre culture ?', '{}'::jsonb, '{"model":"Je comprends l''attachement à cette tradition, mais une tradition peut évoluer. Autrefois, on montrait aussi des animaux enfermés dans des cages pour amuser le public, et on a arrêté. Le cirque peut garder sa magie avec des acrobates, des clowns et des jongleurs, comme le font déjà beaucoup de troupes."}'::jsonb, null), ('qmwh9kjr801j', 'b2po25jrm02h', 2, 'open', 'Et le bien-être animal, finalement, c''est quoi pour vous ?', '{}'::jsonb, '{"model":"Bonne question, je vais essayer d''être précis. Pour moi, un animal est bien traité quand il peut vivre selon ses besoins naturels : bouger, vivre avec ses semblables, ne pas être stressé en permanence. Or, un tigre qui voyage toute l''année dans une remorque ne peut pas vivre ainsi."}'::jsonb, null), ('qmwh9kjr801k', 'b2po25jrm02h', 3, 'open', 'Pourtant, j''ai visité un cirque où les animaux étaient très bien traités.', '{}'::jsonb, '{"model":"Je ne doute pas que certains cirques fassent des efforts. Mais même avec de bons soins, le problème reste le même : les déplacements constants et l''espace limité. Un cas positif ne suffit pas à prouver que le système convient aux animaux sauvages."}'::jsonb, null), ('qmwh9kjr801l', 'b2po25jrm02h', 4, 'open', 'Vous avez un animal, vous ?', '{}'::jsonb, '{"model":"Oui, j''ai un chat, et c''est justement une bonne comparaison : c''est un animal domestique, habitué à vivre avec les humains. Pour en revenir aux cirques, un lion ou un éléphant n''est pas fait pour ce mode de vie, c''est toute la différence."}'::jsonb, null), ('qmwh9kjr801m', 'b2po25jrm02h', 5, 'open', 'Alors, avec votre raisonnement, il faudrait aussi fermer tous les zoos ?', '{}'::jsonb, '{"model":"Pas nécessairement. Tout dépend du zoo. Certains participent à la protection d''espèces menacées et offrent de grands espaces. Je serais plus sévère avec les petits zoos qui gardent les animaux dans des cages trop petites. Mais ce n''est pas tout à fait la même question que celle du cirque."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2po26jrm02i', 'practice', 'Oral B2 : le débat avec l''examinateur', 'B2', array['Production orale']::text[], 'practice', null, null, '<p>Comme à l''examen : l''examinateur vous pose six questions à la suite après votre exposé. Enregistrez chaque réponse sans préparation, comme dans une vraie conversation.</p>', '<p><strong>Situation.</strong> Votre exposé portait sur le surtourisme. Vous avez défendu l''idée qu''il faut limiter le nombre de visiteurs dans les sites les plus célèbres, avec un système de réservation et un droit d''entrée.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• étaler (verbe) : giãn ra, trải ra\n• tirer les leçons (expression) : rút kinh nghiệm\n• un échec (nom masculin) : thất bại\n• hors saison (expression) : ngoài mùa cao điểm\n• une location de courte durée (nom féminin) : cho thuê ngắn ngày","explications":"• Phần tranh luận của đề B2 kéo dài khoảng 10 đến 13 phút: giữ năng lượng đến câu cuối.\n• Câu giả định cuối (« si vous étiez … ») cần conditionnel: « Si j''étais maire, ma première décision serait … ».","ghiAm":true,"isPremium":true,"price":19000,"kyNang":"B2-PO-4","vong":"chot","thuTu":8}'::jsonb, '2026-11-15T12:00:25.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwh9kjr801n', 'b2po26jrm02i', 1, 'open', 'Limiter les visiteurs, c''est réserver les beaux endroits aux riches, non ?', '{}'::jsonb, '{"model":"C''est un risque que je prends au sérieux. C''est pourquoi le droit d''entrée devrait rester modéré, avec des tarifs réduits pour les étudiants et des jours gratuits pour les habitants de la région. L''objectif n''est pas de sélectionner par l''argent, mais d''étaler les visites dans le temps."}'::jsonb, null), ('qmwh9kjr801o', 'b2po26jrm02i', 2, 'open', 'Les touristes font vivre ces villes. Vous voulez tuer l''économie locale ?', '{}'::jsonb, '{"model":"Absolument pas. Je ne propose pas de supprimer le tourisme, mais de mieux l''organiser. Un site abîmé ou une ville où les habitants ne veulent plus vivre finit par attirer moins de visiteurs. Limiter aujourd''hui, c''est protéger les emplois de demain."}'::jsonb, null), ('qmwh9kjr801p', 'b2po26jrm02i', 3, 'open', 'Que voulez-vous dire exactement par « mieux organiser » ?', '{}'::jsonb, '{"model":"Je veux dire concrètement trois choses : une réservation en ligne pour connaître à l''avance le nombre de visiteurs, des horaires élargis pour éviter que tout le monde arrive en même temps, et la promotion de lieux moins connus aux alentours."}'::jsonb, null), ('qmwh9kjr801q', 'b2po26jrm02i', 4, 'open', 'Pourtant, certaines villes ont essayé les quotas et cela n''a pas marché.', '{}'::jsonb, '{"model":"C''est possible, et il faut tirer les leçons de ces échecs. Souvent, le problème vient d''un contrôle insuffisant ou d''une mesure mal expliquée aux habitants. Cela ne prouve pas que l''idée est mauvaise, mais qu''elle doit être appliquée sérieusement et évaluée régulièrement."}'::jsonb, null), ('qmwh9kjr801r', 'b2po26jrm02i', 5, 'open', 'Et vous, quand vous voyagez, vous évitez les endroits touristiques ?', '{}'::jsonb, '{"model":"Je dois reconnaître que non, pas toujours ! Comme tout le monde, j''ai envie de voir les lieux célèbres. Mais j''essaie de partir hors saison et de rester plus longtemps au même endroit. C''est d''ailleurs ce genre de comportement qu''une bonne politique touristique pourrait encourager."}'::jsonb, null), ('qmwh9kjr801s', 'b2po26jrm02i', 6, 'open', 'Pour finir, si vous étiez maire d''une ville très touristique, quelle serait votre première décision ?', '{}'::jsonb, '{"model":"Si j''étais maire, ma première décision serait de limiter les locations de courte durée pour touristes dans le centre, afin que les habitants puissent continuer à se loger. Une ville vivante, avec des écoles et des commerces de quartier, c''est aussi ce qui la rend attirante pour les visiteurs."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
